import * as THREE from "three";
import { Effect } from "postprocessing";

export class WaterEffect extends Effect {
  constructor(options = {}) {
    const fragment = `
      uniform sampler2D uTexture;
      uniform float intensity;

      void mainImage(const in vec4 inputColor, const in vec2 uv, out vec4 outputColor) {
        vec4 displacement = texture2D(uTexture, uv);
        vec2 distortedUv = uv;
        
        // Extract displacement from red and green channels
        distortedUv.x += (displacement.r * 2.0 - 1.0) * intensity;
        distortedUv.y += (displacement.g * 2.0 - 1.0) * intensity;
        
        // Sample the scene with distorted UVs
        vec4 color = texture2D(inputBuffer, distortedUv);
        
        // Add subtle water highlights
        float highlight = pow(1.0 - abs(displacement.r - 0.5) * abs(displacement.g - 0.5), 2.0);
        color.rgb += vec3(0.1, 0.2, 0.3) * highlight * displacement.b;
        
        outputColor = color;
      }
    `;

    super("WaterEffect", fragment, {
      uniforms: new Map([
        ["uTexture", new THREE.Uniform(options.texture)],
        ["intensity", new THREE.Uniform(0.3)]
      ])
    });
  }

  update(renderer, inputBuffer, deltaTime) {
    // Optional: Add any per-frame updates here
  }
}

export default WaterEffect; 